from __future__ import annotations

from typing import Any, Dict

from cache_worker import RateLimitCacheWorker


class OrderProcessor:
    """Coordinate order validation with cache-backed rate limiting."""

    def __init__(self, cache_worker: RateLimitCacheWorker) -> None:
        self.cache_worker = cache_worker

    def process_order(self, order_id: str, user_id: str, amount: float) -> Dict[str, Any]:
